/* BmsInMapper.selectCarryInList : 반입리스트 조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT , SUM(AA.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT , SUM(AA.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT
, SUM(AA.TRY_632_CNT) OVER() AS TOTAL_TRY_632_CNT , SUM(AA.SUCCESS_632_CNT) OVER() AS TOTAL_SUCCESS_632_CNT , SUM(AA.ERROR_632_CNT) OVER() AS TOTAL_ERROR_632_CNT , SUM(AA.TRY_5TL_CNT) OVER() AS TOTAL_TRY_5TL_CNT , SUM(AA.SUCCESS_5TL_CNT) OVER() AS TOTAL_SUCCESS_5TL_CNT , SUM(AA.ERROR_5TL_CNT) OVER() AS TOTAL_ERROR_5TL_CNT FROM ( SELECT A.IN_NO , A.CUSTOMS_REPORT_NO , CONVERT(CHAR(19), A.LAST_POD_DATE , 20) AS LAST_POD_DATE
, (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'STATUS_ORDER_CARGO' AND CODE = A.LAST_POD_STATUS) AS LAST_POD_STATUS , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'STATUS_ORDER_CARGO' AND CODE = A.LAST_POD_5TL_STATUS) AS LAST_POD_5TL_STATUS , A.IN_CLASS + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'CARRYIN_TYPE' AND CODE = A.IN_CLASS) AS IN_CLASS , A.CD_TYPE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'CD_TYPE' AND CODE = A.CD_TYPE) AS CD_TYPE , A.CD_USE_TYPE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'USE_GUBN' AND CODE = A.CD_USE_TYPE ) AS CD_USE_TYPE , A.ECM_TYPE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'CCL_ECOMMERCE_TYPE' AND CODE = A.ECM_TYPE) AS ECM_TYPE , A.IMPORT_EXPORT_CLASS + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'BOUND_TYPE_UNION' AND CODE = A.IMPORT_EXPORT_CLASS) AS IMPORT_EXPORT_CLASS , A.SE_INSPECTION_CODE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'SE_INSPECTION_CODE' AND CODE = A.SE_INSPECTION_CODE) AS SE_INSPECTION_CODE , A.INSPECTION_TYPE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'INSPECTION_TYPE' AND CODE = A.INSPECTION_TYPE) AS INSPECTION_TYPE , A.INSPECTION_TYPE_A + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'INSPECTION_TYPE' AND CODE = A.INSPECTION_TYPE_A) AS INSPECTION_TYPE_A , A.INSPECTION_TYPE_B + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'INSPECTION_TYPE' AND CODE = A.INSPECTION_TYPE_B) AS INSPECTION_TYPE_B , A.XRAY_INSPECTION_CODE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'SE_INSPECTION_CODE' AND CODE = A.XRAY_INSPECTION_CODE) AS XRAY_INSPECTION_CODE , A.XRAY_CHECK + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'XRAY_INSPECTION_TYPE' AND CODE = A.XRAY_CHECK) AS XRAY_CHECK , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'XRAY_LINE_NO' AND CODE = A.XRAY_LINE_NO) AS XRAY_LINE_NO , A.PALN5EM_INSPECTION_CODE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'SE_INSPECTION_CODE' AND CODE = A.PALN5EM_INSPECTION_CODE) AS PALN5EM_INSPECTION_CODE
, A.LAST_POD_STATUS , A.LAST_POD_5TL_STATUS , A.IN_CLASS , A.CD_TYPE , A.CD_USE_TYPE , A.ECM_TYPE , A.IMPORT_EXPORT_CLASS , A.SE_INSPECTION_CODE , A.INSPECTION_TYPE , A.INSPECTION_TYPE_A , A.INSPECTION_TYPE_B , xr.XRAY_INSPECTION_CODE , A.XRAY_CHECK , xr.XRAY_LINE_NO , A.PALN5EM_INSPECTION_CODE
, CONVERT(CHAR(19), A.LAST_POD_RAQ_DATE , 20) AS LAST_POD_RAQ_DATE , A.LAST_POD_R48_DATE , A.IN_APPROVAL_NO , A.TRANS_PERIOD_DATE , A.OD_JOB_NO , A.IN_PLAN_NO , A.CARGO_REFERENCE_NO , CASE WHEN LEN(A.CARGO_REFERENCE_NO) > 15 THEN ( SUBSTRING(A.CARGO_REFERENCE_NO, 1, 11) + '-' + SUBSTRING(A.CARGO_REFERENCE_NO, 12, 4) + '-' + SUBSTRING(A.CARGO_REFERENCE_NO, 16, 4) ) ELSE SUBSTRING(A.CARGO_REFERENCE_NO, 1, 11) + '-' + SUBSTRING(A.CARGO_REFERENCE_NO, 12, 4) END AS CARGO_REFERENCE_NO_DISP , A.BL_NO , A.MBL_NO , A.CUSTOMS_CODE , A.CUSTOMS_DPT_CODE , A.INSPECT_YN , A.NOTICE_INSPECT_YN , A.LOCATION_PLACE , A.VESSEL_FLIGHT , A.VOYAGE , A.AR_DATE , A.AR_TIME , A.COMMODITY_ITEM_LOC , A.SHIPPER_CODE , A.SHIPPER_NAME , A.SHIPPER_ADDRESS_1 , A.SHIPPER_ADDRESS_2 , dbo.Cryptography(A.OD_JOB_NO, A.SHIPPER_TEL, 1) AS SHIPPER_TEL , A.CONSIGNEE_CODE , A.CONSIGNEE_NAME , A.CONSIGNEE_ADDRESS_1 , A.CONSIGNEE_ADDRESS_2 , dbo.Cryptography(A.OD_JOB_NO, A.CONSIGNEE_BUSINESS_ID, 1) AS CONSIGNEE_BUSINESS_ID , dbo.Cryptography(A.OD_JOB_NO, A.CONSIGNEE_TEL, 1) AS CONSIGNEE_TEL , A.NOTIFY_CODE , A.NOTIFY_NAME , A.NOTIFY_ADDRESS_1 , A.NOTIFY_ADDRESS_2 , dbo.Cryptography(A.OD_JOB_NO, A.NOTIFY_TEL, 1) AS NOTIFY_TEL , A.DELIVERY_CODE , A.DELIVERY_NAME , A.SPECIAL_CODE_1 , A.SPECIAL_CODE_2 , A.SPECIAL_CODE_3 , A.CARRIER_CODE , A.CNTR_NO , A.ORIG_COUNTRY , A.SIMPLE_AUTH_NAME , IIF(A.CD_TYPE = 'Y', 1, 0) AS SIMPLE_CNT , IIF(ISNULL(A.CD_TYPE, '') != 'Y', 1, 0) AS GENERAL_CNT , CASE WHEN A.LAST_POD_STATUS IN ('BMS03', 'BMS04', 'BMS05', 'BMSA1', 'BMSA2') THEN 1 ELSE 0 END AS TRY_632_CNT , CASE WHEN A.LAST_POD_STATUS = 'BMS04' THEN 1 ELSE 0 END AS SUCCESS_632_CNT , CASE WHEN A.LAST_POD_STATUS IN ('BMS05', 'BMSA1', 'BMSA2') THEN 1 ELSE 0 END AS ERROR_632_CNT
, CASE WHEN A.LAST_POD_5TL_STATUS IN ('BMS03', 'BMS04', 'BMS05') THEN 1 ELSE 0 END AS TRY_5TL_CNT , CASE WHEN A.LAST_POD_5TL_STATUS = 'BMS04' THEN 1 ELSE 0 END AS SUCCESS_5TL_CNT , CASE WHEN A.LAST_POD_5TL_STATUS IN ('BMS05') THEN 1 ELSE 0 END AS ERROR_5TL_CNT , A.BIG_SIZE_YN , A.AMOUNT_USD , xr.XRAY_SCAN_CT , xr.XRAY_IMAGE_CT , A.CARRYIN_DATE , A.CARRYIN_TIME , A.OUT_NOTICE_DATE , A.PERIOD_OVER_DATE , A.CUSTOMER_CODE , A.CUSTOMER_NAME , A.FWD_CODE , A.FWD_NAME , A.PKG_TYPE , A.EX_CT , A.EX_WT , A.EX_CBM , A.CT , A.WT , A.CBM , A.ACCIDENT_CLASS , A.ACCIDENT_CT , A.ACCIDENT_WT , A.ACCIDENT_CBM , A.STOCK_CT , A.STOCK_WT , A.STOCK_CBM , A.CARRYOUT_DATE , A.CARRYOUT_TIME , A.REMARKS_1 , A.REMARKS_2 , A.REMARKS_3 , A.REFERENCE_NO , A.MGN_ISSUE_YN , A.REGISTER_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = A.REGISTER_USER_ID) AS REGISTER_USER_NAME , A.REGISTER_DATE_TIME , A.UPDATE_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = A.UPDATE_USER_ID) AS UPDATE_USER_NAME , A.UPDATE_DATE_TIME , A.ASSIGN_YN , A.CRIME_SELECTION_YN , A.INTELLECTUAL_PROP_YN , A.INSPECTION_CUSTOMS_YN , 'CARRY_IN' AS CARRY_IN_STATE , ISNULL(oh.HOLD_YN,'N') AS HOLD_YN , oh.HOLD_CODE , oh.HOLD_REASON , oh.HOLD_RELEASE_YN , oh.HOLD_RELEASE_ATTN , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = oh.HOLD_RELEASE_ATTN) AS HOLD_RELEASE_ATTN_NAME , oh.HOLD_RELEASE_DATE , CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE FUNC_JOB_NO = A.OD_JOB_NO) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE , teoa.DROP_YN , INPKG.PACKING_CT_SUM , xr.INSPECTOR_ID FROM TB_BMS_IN A WITH (NOLOCK) LEFT JOIN (SELECT '' AS HOLD_YN , MAX(OD_JOB_NO) AS OD_JOB_NO , MAX(HOLD_CODE) AS HOLD_CODE , MAX(HOLD_REASON) AS HOLD_REASON , MAX(HOLD_RELEASE_YN) AS HOLD_RELEASE_YN , MAX(HOLD_RELEASE_ATTN) AS HOLD_RELEASE_ATTN , MAX(HOLD_RELEASE_DATE) AS HOLD_RELEASE_DATE FROM TB_ECM_OD_HOLD GROUP BY OD_JOB_NO ) oh ON oh.OD_JOB_NO = A.OD_JOB_NO LEFT JOIN (SELECT OD_JOB_NO, DROP_YN FROM TB_ECM_OD_ADDITIONAL) teoa ON teoa.OD_JOB_NO = A.OD_JOB_NO LEFT JOIN TB_BMS_XRAY_RESULT xr ON xr.IN_PLAN_NO = A.IN_PLAN_NO LEFT JOIN ( SELECT IN_PLAN_NO, SUM(PACKING_CT) AS PACKING_CT_SUM FROM TB_BMS_IN_PLAN_PKG WHERE DELETE_YN = 'N' GROUP BY IN_PLAN_NO) INPKG ON INPKG.IN_PLAN_NO = A.IN_PLAN_NO
AND A.LAST_POD_STATUS = #{srchLastPodStatus}
AND A.LAST_POD_5TL_STATUS = #{srchLastPod5TlStatus}
AND A.XRAY_LINE_NO IN (#{item})
AND A.XRAY_INSPECTION_CODE IN (#{item})
AND oh.HOLD_CODE IN (#{item})
AND A.IN_CLASS = #{srchCarryInType}
AND 1 = 0
) AA

/* BmsinMapper.selectDetailCarryIn : 반입상세 한 건 조회 */ SELECT
bi.IN_NO , bi.CUSTOMS_REPORT_NO , CONVERT(CHAR(19), bi.LAST_POD_DATE , 20) AS LAST_POD_DATE , bi.LAST_POD_STATUS , bi.LAST_POD_5TL_STATUS , CONVERT(CHAR(19), bi.LAST_POD_RAQ_DATE , 20) AS LAST_POD_RAQ_DATE , bi.LAST_POD_R48_DATE , bi.IN_CLASS , bi.IN_APPROVAL_NO , bi.TRANS_PERIOD_DATE , bi.OD_JOB_NO , bi.IN_PLAN_NO , bi.CARGO_REFERENCE_NO , bi.BL_NO , bi.MBL_NO , bi.CUSTOMS_CODE , bi.CUSTOMS_DPT_CODE , bi.INSPECT_YN , bi.NOTICE_INSPECT_YN , bi.LOCATION_PLACE , bi.IMPORT_EXPORT_CLASS , bi.VESSEL_FLIGHT , bi.VOYAGE , bi.AR_DATE , bi.AR_TIME , bi.COMMODITY_ITEM_LOC , bi.SHIPPER_CODE , bi.SHIPPER_NAME , bi.SHIPPER_ADDRESS_1 , bi.SHIPPER_ADDRESS_2 , bi.CONSIGNEE_CODE , bi.CONSIGNEE_NAME , bi.CONSIGNEE_ADDRESS_1 , bi.CONSIGNEE_ADDRESS_2 , dbo.Cryptography(bi.OD_JOB_NO, bi.CONSIGNEE_BUSINESS_ID, 1) AS CONSIGNEE_BUSINESS_ID , dbo.Cryptography(bi.OD_JOB_NO, bi.CONSIGNEE_TEL, 1) AS CONSIGNEE_TEL , bi.NOTIFY_CODE , bi.NOTIFY_NAME , bi.NOTIFY_ADDRESS_1 , bi.NOTIFY_ADDRESS_2 , dbo.Cryptography(bi.OD_JOB_NO, bi.NOTIFY_TEL, 1) AS NOTIFY_TEL , bi.SPECIAL_CODE_1 , bi.SPECIAL_CODE_2 , bi.SPECIAL_CODE_3 , bi.CARRIER_CODE , bi.CNTR_NO , bi.ORIG_COUNTRY , bi.SE_INSPECTION_CODE , bi.SIMPLE_AUTH_NAME , bi.INSPECTION_TYPE , bi.INSPECTION_TYPE_A , bi.INSPECTION_TYPE_B , bi.XRAY_INSPECTION_CODE , bi.XRAY_LINE_NO , bi.XRAY_CHECK , bi.PALN5EM_INSPECTION_CODE , bi.CD_TYPE , bi.ECM_TYPE , bi.CD_USE_TYPE , bi.BIG_SIZE_YN , bi.AMOUNT_USD , bi.XRAY_SCAN_CT , bi.XRAY_IMAGE_CT , bi.CARRYIN_DATE , CONVERT(CHAR(8), CONVERT(DATETIME,bi.CARRYIN_TIME), 24) AS CARRYIN_TIME , bi.OUT_NOTICE_DATE , bi.PERIOD_OVER_DATE , bi.CUSTOMER_CODE , bi.CUSTOMER_NAME , bi.FWD_CODE , bi.FWD_NAME , bi.PKG_TYPE , bi.EX_CT , bi.EX_WT , bi.EX_CBM , bi.CT , bi.WT , bi.CBM , bi.ACCIDENT_CLASS , bi.ACCIDENT_CT , bi.ACCIDENT_WT , bi.ACCIDENT_CBM , bi.STOCK_CT , bi.STOCK_WT , bi.STOCK_CBM , bi.CARRYOUT_DATE , CONVERT(CHAR(8), CONVERT(DATETIME,bi.CARRYOUT_TIME), 24) AS CARRYOUT_TIME , bi.REMARKS_1 AS 'REMARKS1' , bi.REMARKS_2 AS 'REMARKS2' , bi.REMARKS_3 AS 'REMARKS3' , bi.REFERENCE_NO , bi.MGN_ISSUE_YN , bi.REGISTER_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = bi.REGISTER_USER_ID) AS REGISTER_USER_NAME , bi.REGISTER_DATE_TIME , bi.UPDATE_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = bi.UPDATE_USER_ID) AS UPDATE_USER_NAME , bi.UPDATE_DATE_TIME , bi.DELIVERY_CODE , bi.DELIVERY_NAME , bi.ASSIGN_YN , bi.CRIME_SELECTION_YN , bi.INTELLECTUAL_PROP_YN , bi.INSPECTION_CUSTOMS_YN , ISNULL(oh.HOLD_YN,'N') AS HOLD_YN , oh.HOLD_CODE , oh.HOLD_REASON , oh.HOLD_RELEASE_YN , oh.HOLD_RELEASE_ATTN , oh.HOLD_RELEASE_DATE
, (SELECT MAX(OUT_NO) FROM TB_BMS_OUT WITH (NOLOCK) WHERE IN_NO = bi.IN_NO) AS OUT_NO
FROM TB_BMS_IN_CHANGE_DEL bi
FROM TB_BMS_IN bi WITH (NOLOCK)
LEFT JOIN (SELECT '' AS HOLD_YN , MAX(OD_JOB_NO) AS OD_JOB_NO , MAX(HOLD_CODE) AS HOLD_CODE , MAX(HOLD_REASON) AS HOLD_REASON , MAX(HOLD_RELEASE_YN) AS HOLD_RELEASE_YN , MAX(HOLD_RELEASE_ATTN) AS HOLD_RELEASE_ATTN , MAX(HOLD_RELEASE_DATE) AS HOLD_RELEASE_DATE FROM TB_ECM_OD_HOLD GROUP BY OD_JOB_NO ) oh ON oh.OD_JOB_NO = bi.OD_JOB_NO WHERE 1 = 1
AND bi.IN_PlAN_NO = #{inPlanNo}
AND bi.IN_NO = #{inNo}

mapper.insert:
/* BmsInMapper.insertHandInputCarryIn */

INSERT INTO TB_BMS_IN (
CUSTOMS_REPORT_NO
, OD_JOB_NO
, LAST_POD_STATUS
, LAST_POD_DATE
, LAST_POD_RAQ_DATE
, LAST_POD_R48_DATE
, AR_DATE
, VESSEL_FLIGHT
, BL_NO
, MBL_NO
, CARGO_REFERENCE_NO
, IN_CLASS
, IN_APPROVAL_NO
, LOCATION_PLACE
, CARRYIN_DATE
, CARRYIN_TIME
, TRANS_PERIOD_DATE
, PKG_TYPE
, ACCIDENT_CLASS
, COMMODITY_ITEM_LOC
, CUSTOMER_CODE
, CUSTOMER_NAME
, EX_CT
, EX_WT
, EX_CBM
, CT
, WT
, CBM
, ACCIDENT_CT
, ACCIDENT_WT
, ACCIDENT_CBM
, STOCK_CT
, STOCK_WT
, STOCK_CBM
, REMARKS_1
, REMARKS_2
, REMARKS_3
, CD_TYPE
, CD_USE_TYPE
, AMOUNT_USD
, SE_INSPECTION_CODE
, XRAY_INSPECTION_CODE
, PALN5EM_INSPECTION_CODE
, XRAY_CHECK
, XRAY_LINE_NO
, INSPECTION_TYPE
, INSPECTION_TYPE_A
, INSPECTION_TYPE_B
, IMPORT_EXPORT_CLASS
, ORIG_COUNTRY
, CONSIGNEE_CODE
, CONSIGNEE_NAME
, SHIPPER_CODE
, SHIPPER_NAME
, NOTIFY_CODE
, NOTIFY_NAME
, DELIVERY_CODE
, DELIVERY_NAME
, OUT_NOTICE_DATE
, PERIOD_OVER_DATE
, REGISTER_USER_ID
, REGISTER_DATE_TIME
, UPDATE_USER_ID
, UPDATE_DATE_TIME
)
VALUES (
#{customsReportNo}
, #{blNo} /**수기입력시 OD_JOB_NO 에 BL번호 입력*/
, CASE WHEN #{inClass} = '23' THEN 'BMS04' ELSE 'BMS01' END
, ''
, ''
, ''
, #{arDate}
, #{vesselFlight}
, #{blNo}
, #{mblNo}
, #{cargoReferenceNo}
, #{inClass}
, #{inApprovalNo}
, UPPER(#{locationPlace})
, CONVERT(DATE,  #{carryinDate}, ${dateFormat})
, #{carryinTime}
, CONVERT(DATE,  #{transPeriodDate}, ${dateFormat})
, #{pkgType}
, #{accidentClass}
, #{commodityItemLoc}
, #{customerCode}
, #{customerName}
, #{exCt}
, #{exWt}
, #{exCbm}
, #{ct}
, #{wt}
, #{cbm}
, #{accidentCt}
, #{accidentWt}
, #{accidentCbm}
, #{stockCt}
, #{stockWt}
, #{stockCbm}
, #{remarks1}
, #{remarks2}
, #{remarks3}
, 'N'
, #{cdUseType}
, #{amountUsd}
, #{seInspectionCode}
, #{xrayInspectionCode}
, #{paln5emInspectionCode}
, #{xrayCheck}
, #{xrayLineNo}
, #{inspectionType}
, #{inspectionTypeA}
, #{inspectionTypeB}
, #{importExportClass}
, #{origCountry}
, #{consigneeCode}
, #{consigneeName}
, #{shipperCode}
, #{shipperName}
, #{notifyCode}
, #{notifyName}
, #{deliveryCode}
, #{deliveryName}
, CONVERT(DATE,  #{outNoticeDate}, ${dateFormat})
, CONVERT(DATE,  #{periodOverDate}, ${dateFormat})
, #{registerUserId}
, GETDATE()
, #{updateUserId}
, GETDATE()
)

