mapper.update:
/* BmsInMapper.updateBmsInPlanInYn */
update TB_BMS_IN_PLAN SET
	IN_YN       	  = #{inYn},
	UPDATE_USER_ID    = #{updateUserId},
	UPDATE_DATE_TIME  = GETDATE()
where IN_PLAN_NO = #{inPlanNo}

/* BmsinMapper.updateCarryIn  : 반입정보 수정 */
UPDATE TB_BMS_IN SET
	  AR_DATE					= #{arDate}
	, VESSEL_FLIGHT			    = #{vesselFlight}
	, IN_CLASS					= #{inClass}
	, IN_APPROVAL_NO			= #{inApprovalNo}
	, LOCATION_PLACE			= #{locationPlace}
	, CARRYIN_DATE				= #{carryinDate}
	, CARRYIN_TIME				= #{carryinTime}
	, OUT_NOTICE_DATE           = #{outNoticeDate}
	, PERIOD_OVER_DATE          = #{periodOverDate}
	, TRANS_PERIOD_DATE			= #{transPeriodDate}
	, PKG_TYPE					= #{pkgType}
	, ACCIDENT_CLASS			= #{accidentClass}
	, COMMODITY_ITEM_LOC		= #{commodityItemLoc}
	, CUSTOMER_CODE				= #{customerCode}
	, CUSTOMER_NAME				= #{customerName}
	, EX_CT						= #{exCt}
	, EX_WT						= #{exWt}
	, EX_CBM					= #{exCbm}
	, CT						= #{ct}
	, WT						= #{wt}
	, CBM						= #{cbm}
	, ACCIDENT_CT				= #{accidentCt}
	, ACCIDENT_WT				= #{accidentWt}
	, ACCIDENT_CBM				= #{accidentCbm}
	, STOCK_CT					= #{stockCt}
	, STOCK_WT					= #{stockWt}
	, STOCK_CBM					= #{stockCbm}
	, REMARKS_1					= #{remarks1}
	, REMARKS_2					= #{remarks2}
	, REMARKS_3					= #{remarks3}
	, PALN5EM_INSPECTION_CODE	= #{paln5emInspectionCode}
	, XRAY_CHECK				= #{xrayCheck}
	, IMPORT_EXPORT_CLASS      	= #{importExportClass}
	, CONSIGNEE_CODE			= #{consigneeCode}
	, CONSIGNEE_NAME			= #{consigneeName}
	, SHIPPER_CODE				= #{shipperCode}
	, SHIPPER_NAME				= #{shipperName}
	, NOTIFY_CODE				= #{notifyCode}
	, NOTIFY_NAME				= #{notifyName}
	, DELIVERY_CODE				= #{deliveryCode}
	, DELIVERY_NAME				= #{deliveryName}
	, UPDATE_USER_ID			= #{updateUserId}
	, UPDATE_DATE_TIME			= GETDATE()

	, LAST_POD_STATUS = 'BMS01'
	, LAST_POD_DATE = ''


	, LAST_POD_STATUS = 'BMS01'
	, LAST_POD_DATE = ''
	, LAST_POD_RAQ_DATE = ''

	, ASSIGN_YN					= #{assignYn}
WHERE 1 = 1
AND IN_NO = #{inNo}

mapper.select:
     /* BmsInMapper.selectCarryInBatchCheckReceiptCount */
		SELECT * FROM TB_ECM_POD_05 WITH (NOLOCK)
		WHERE OD_JOB_NO = #{odJobNo}

     /* BmsInMapper.selectCarryInBatchCheckReceiptCount */
		SELECT count(*) FROM TB_BMS_IN WITH (NOLOCK)
		WHERE LAST_POD_STATUS != 'BMS04'
		  AND IN_NO = #{inNo}

/* BmsInMapper.selectCheckBmsIn21Count : 화물관리번호에 해당하는 재고가있는 이고반입 count */
SELECT count(*) 
FROM TB_BMS_IN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
  AND IN_CLASS ='21'

/* BmsInMapper.selectCheck61CarryOutByInNo : 반입번호에 맵핑되는 이고반출 count */
SELECT count(*) FROM TB_BMS_OUT WITH (NOLOCK)
WHERE IN_NO = #{inNo}
  AND OUT_CLASS ='61'
  AND OUT_APPROVAL_NO ='04002001'

/* BmsInMapper.selectCarryInBatchCheckOutCount */
SELECT count(*) FROM TB_BMS_IN tbi WITH (NOLOCK) INNER JOIN TB_BMS_OUT tbo WITH(NOLOCK) ON tbi.IN_NO = tbo.IN_NO WHERE tbi.IN_NO = #{inNo}
AND tbo.OUT_CLASS ='61' AND tbo.OUT_APPROVAL_NO ='04002001'

/* BmsInMapper.selectBatchCheckOutCountByOutClass : 반출구분 조건에 해당하는 반출 조회 */
SELECT count(*) FROM TB_BMS_OUT WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
  AND OUT_CLASS = '70'

/* BmsInMapper.checkCarryInBigsizeCount : 반입의 거대_지재_집중_우범_체크 */
SELECT COUNT(*) FROM TB_BMS_IN WITH (NOLOCK)
WHERE IN_NO = #{inNo}
  AND BIG_SIZE_YN != 'Y' /* 거대 */
  AND INTELLECTUAL_PROP_YN != 'Y' /* 지재권 */
  AND INSPECTION_CUSTOMS_YN != 'Y' /* 집중검사 */

		/* BmsInMapper.checkCarryInBatchTicCount2  이고대상이 아닌건 조회 */
		 SELECT COUNT(*) 
	 	  FROM TB_BMS_INSPECT_RESULT WITH (NOLOCK)
	 	  WHERE IN_NO = #{inNo}

	 	  AND INSPECTION_TYPE IN (
