/* BmsInMapper.selectBmsInLastPodResendCheckList : 반입 화물속성(5TL)재전송 여러건 조회 */
SELECT bmi.IN_NO AS inNo ,bmi.IN_PLAN_NO AS inPlanNo ,bmi.OD_JOB_NO AS odJobNo ,SUM(IIF(bmi.LAST_POD_STATUS='BMS04',1,0)) OVER() AS lastPodCnt ,bmi.BL_NO AS blNo ,bmi.MBL_NO AS mblNo ,bmi.CARGO_REFERENCE_NO AS cargoReferenceNo ,ISNULL(bmi.CT,0) AS ct ,SUM(ISNULL(bmi.CT,0)) OVER() AS ctSum ,SUM(IIF(bmi.BIG_SIZE_YN='Y',1,0)) OVER() AS bigSizeCnt ,MAX(ISNULL(xr.XRAY_INSPECTION_CODE, '')) OVER() AS xrayInspectionCode ,SUM(ISNULL(xr.XRAY_IMAGE_CT, 0)) OVER() AS xrayImageCtSum ,COUNT(bmi.IN_NO) OVER() AS cnt FROM TB_BMS_IN bmi WITH (NOLOCK) LEFT JOIN TB_BMS_XRAY_RESULT xr ON xr.IN_PLAN_NO = bmi.IN_PLAN_NO WHERE IN_NO IN
#{item.inNo}
ORDER BY bmi.IN_NO

/* BmsInMapper.selectBmsOutLastPodCheckList */
WITH OUT_DATA AS ( SELECT CARGO_REFERENCE_NO FROM TB_BMS_OUT WITH (NOLOCK) WHERE CARGO_REFERENCE_NO IN
#{item.cargoReferenceNo}
AND OUT_CLASS = '61' GROUP BY CARGO_REFERENCE_NO ) SELECT count(CARGO_REFERENCE_NO) FROM OUT_DATA

/* BmsInMapper.selectBmsXrayResultCheckList : 반입 화물속성(5TL)재전송 XRAY 여러건 조회 */
SELECT TOP 1 COUNT(IN_PLAN_NO) OVER() AS CNT ,MAX(ISNULL(XRAY_INSPECTION_CODE,'')) OVER() AS XRAY_INSPECTION_CODE FROM TB_BMS_XRAY_RESULT WHERE IN_PLAN_NO IN
#{item.inPlanNo}

/* BmsInMapper.selectCargoByOutPlanNo */
SELECT OUT_PLAN_NO
FROM TB_BMS_OUT_PLAN WITH (NOLOCK) 
WHERE APPROVAL_CLASS = '31'
AND CARGO_REFERENCE_NO = #{cargoReferenceNo}
AND IN_NO = 0

mapper.update:
/* BmsInMapper.updateNo : */
UPDATE TB_BMS_OUT_PLAN SET
	  IN_NO = #{inNo}
	, BL_NO     = #{blNo}
	, MBL_NO   = #{mblNo}
WHERE OUT_PLAN_NO = #{outPlanNo}

/* BmsInMapper.updatePodStatus : 타창고하기 설정 진행상태 업데이트 */
UPDATE TB_BMS_IN SET
	LAST_POD_STATUS = 'BMSA1'
WHERE IN_NO = #{inNo}

mapper.select:
/* BmsInMapper.selectLastPodStatusByInNo : 타창고하기 설정 반출자료 확인 */
SELECT 
	LAST_POD_STATUS
	,OUT_NO
FROM TB_BMS_OUT WITH (NOLOCK) 
WHERE IN_NO = #{inNo}

mapper.update:
/* BmsInMapper.updateOutPodStatus : 타창고하기 설정 반출 쪽 진행상태 업데이트 */
UPDATE TB_BMS_OUT SET
	LAST_POD_STATUS = 'BMSA1'
WHERE OUT_NO = #{outNo}

/* BmsInMapper.updatePodStatusClear : 타창고하기 해제 진행상태 업데이트 */
UPDATE TB_BMS_IN SET
	LAST_POD_STATUS = 'BMS01'
WHERE IN_NO = #{inNo}

/* BmsInMapper.updateOutPodStatusClear : 타창고하기 해제 반출 쪽 진행상태 업데이트 */
UPDATE TB_BMS_OUT SET
	LAST_POD_STATUS = 'BMS01'
WHERE OUT_NO = #{outNo}

mapper.select:
/* BmsInMapper.selectFirstBmsInByCargoNo : 화물관리번호에 해당하는 최초 반입 */
SELECT TOP 1
	*
FROM TB_BMS_IN WITH (NOLOCK) 
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}

mapper.update:
/* BmsInMapper.updateOrigInPlanNoOfBmsInByInNo : 반입번호에 해당하는 반입의 원본반입예정번호를 update */
UPDATE TB_BMS_IN SET
	ORIG_IN_PLAN_NO = #{origInPlanNo}
WHERE IN_NO = #{inNo}

/* BmsInMapper.updatePkgTicMoveInByInPlanNo : 반입예정번호에 해당하는 박스 이고입고수량 업데이트 */
UPDATE TB_BMS_IN_PLAN_PKG
SET
	MOVE_IN_CT = #{moveInCt}

	, MOVE_OUT_CT = #{moveOutCt}

	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE IN_PLAN_NO = #{inPlanNo}

mapper.select:
/* BmsInMapper.selectHoldStatusByOdJobNo : 일괄홀드 데이터 확인 */
SELECT 
	OD_JOB_NO
	,HOLD_CODE
	,CARRYOUT_STOP_YN
	,HOLD_RELEASE_YN
FROM TB_ECM_OD_HOLD WITH (NOLOCK) 
WHERE OD_JOB_NO = #{odJobNo}
AND HOLD_CODE = #{srchHoldCode}

mapper.update:
/* BmsInMapper.updateHoldOnClear : 일괄홀드해제처리 */
UPDATE TB_ECM_OD_HOLD SET
	CARRYOUT_STOP_YN		= 'N'
	,HOLD_RELEASE_YN		= 'Y'
	,HOLD_RELEASE_REASON	= '일괄홀드해제'
	,HOLD_RELEASE_ATTN		= #{updateUserId}
	,HOLD_RELEASE_DATE		= (CAST(GETDATE() AS DATE))
WHERE OD_JOB_NO = #{odJobNo}
AND HOLD_CODE = #{srchHoldCode}

/* BmsInMapper.updateXrayCtClear : X-Ray판독수량 초기화 수량 업데이트 */
UPDATE TB_BMS_XRAY_RESULT SET
	XRAY_SCAN_CT = 0
	,XRAY_IMAGE_CT = 0
WHERE IN_PLAN_NO = #{inPlanNo}

/* BmsInMapper.updateCarryInXrayCtClear : 반입 X-Ray 판독/이미지 수량 초기화 */
UPDATE TB_BMS_IN SET
	XRAY_SCAN_CT = 0
	,XRAY_IMAGE_CT = 0
	,UPDATE_USER_ID = #{updateUserId}
	,UPDATE_DATE_TIME = GETDATE()
WHERE IN_NO = #{inNo}
